import { useState, useCallback, useEffect } from 'react';
import { LLMService, defaultLLMConfigs } from '../services/llmService';
import { LLMConfig, LLMResponse, ChatSettings } from '../types';

export const useLLM = () => {
  const [llmService, setLLMService] = useState<LLMService | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [settings, setSettings] = useState<ChatSettings>({
    selectedLLM: 'gemini',
    geminiConfig: {
      apiKey: process.env.REACT_APP_GEMINI_API_KEY || '',
      model: 'gemini-pro',
      temperature: 0.7
    },
    vllmConfig: {
      baseUrl: process.env.REACT_APP_VLLM_BASE_URL || 'http://localhost:8000',
      model: 'llama-2-7b-chat',
      temperature: 0.7,
      maxTokens: 1000
    }
  });

  // Initialize LLM service when settings change
  useEffect(() => {
    const config: LLMConfig = settings.selectedLLM === 'gemini' 
      ? {
          provider: 'gemini',
          apiKey: settings.geminiConfig.apiKey,
          model: settings.geminiConfig.model,
          temperature: settings.geminiConfig.temperature
        }
      : {
          provider: 'vllm',
          baseUrl: settings.vllmConfig.baseUrl,
          model: settings.vllmConfig.model,
          temperature: settings.vllmConfig.temperature,
          maxTokens: settings.vllmConfig.maxTokens
        };

    try {
      const service = new LLMService(config);
      setLLMService(service);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to initialize LLM service');
      setLLMService(null);
    }
  }, [settings]);

  const generateResponse = useCallback(async (
    prompt: string, 
    conversationHistory?: string[]
  ): Promise<LLMResponse> => {
    if (!llmService) {
      throw new Error('LLM service not initialized');
    }

    setIsLoading(true);
    setError(null);

    try {
      const response = await llmService.generateResponse(prompt, conversationHistory);
      return response;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to generate response';
      setError(errorMessage);
      throw new Error(errorMessage);
    } finally {
      setIsLoading(false);
    }
  }, [llmService]);

  const switchLLM = useCallback((provider: 'gemini' | 'vllm') => {
    setSettings(prev => ({
      ...prev,
      selectedLLM: provider
    }));
  }, []);

  const updateGeminiConfig = useCallback((config: Partial<ChatSettings['geminiConfig']>) => {
    setSettings(prev => ({
      ...prev,
      geminiConfig: { ...prev.geminiConfig, ...config }
    }));
  }, []);

  const updateVLLMConfig = useCallback((config: Partial<ChatSettings['vllmConfig']>) => {
    setSettings(prev => ({
      ...prev,
      vllmConfig: { ...prev.vllmConfig, ...config }
    }));
  }, []);

  const isConfigured = useCallback(() => {
    if (settings.selectedLLM === 'gemini') {
      return !!settings.geminiConfig.apiKey;
    } else {
      return !!settings.vllmConfig.baseUrl;
    }
  }, [settings]);

  return {
    generateResponse,
    isLoading,
    error,
    settings,
    switchLLM,
    updateGeminiConfig,
    updateVLLMConfig,
    isConfigured,
    currentProvider: settings.selectedLLM
  };
};
